function daily(){const claimed=s.daily.date===R.dateKey(),day=claimed?(s.daily.day+6)%7:s.daily.day%7;showModal('里からの贈り物',`<p class="small">日本時間の0時に切り替わります<br>受け取れない日があっても、続きの日から再開</p><div class="daily">${Array.from({length:7},(_,i)=>`<div class="${i<day||i===day&&claimed?'claimed':i===day?'today':''}">${i+1}日目<strong>${R.dailyReward(i).coin}銭</strong><span>晶${R.dailyReward(i).dust}</span></div>`).join('')}</div><p class="note">今回：${cost(R.dailyReward(day))} ／ 灯輝石5</p>${btn('claim',claimed?'今日は受取済み':'受け取る','primary',claimed?'disabled':'')}<p class="small">端末内のログインボーナス<br>7日目を受け取ると1日目に戻ります</p>`);}
function grow(key){const id=selected,h=s.heroes[id],c=key==='rank'?R.rankCost(s,id):R.skillCost(s,id,key),copy=R.copy(s);if(!R.grow(copy,id,key)){toast(key==='rank'?'ゴールドか覚醒印が足りません':'レベルか素材が足りません');return;}confirm(key==='rank'?'覚醒しますか？':'技を強化しますか？',`<h3>${R.chars[id][key]||R.chars[id].name+'の覚醒'}</h3>${key==='rank'||key==='passive'?changes(R.stats(s,id),R.stats(copy,id)):`<p class="note">${skillDesc(id,key,h.skills[key])}<br>↓<br>${skillDesc(id,key,copy.heroes[id].skills[key])}</p>`}<p class="small">消費 ${cost(c)}</p>`,()=>{const beforePower=R.total(s);if(!R.grow(s,id,key))return;teleGrowth(key==='rank'?'awaken':'skill_upgrade',1,R.total(s)-beforePower);closeModal();render();toast(R.chars[id].name+' '+(key==='rank'?'覚醒 '+s.heroes[id].rank:R.chars[id][key]+' Lv.'+s.heroes[id].skills[key]));A.sfx('awaken');});}
