function continueResult(){const r=s.run;if(!r)return;if(r.festival!==undefined){festivalPage();return;}if(r.tower){if(X.canTower(s,r.tower+1))beginTower(r.tower+1);else{toHome();navigate('map');adventureTab='tower';render();}return;}autoNextAt=0;const pages=[...(r.stage<3?[]:(r.events||[])).map(e=>({who:e.memberId==='party'?'仲間たち':R.chars.find(c=>c.key===e.memberId)?.name||'アレン',text:e.text})),...(r.ending||[])];if(pages.length&&!r.storyRead){r.storyRead=true;story(pages,s.onboarding&&s.onboarding.step==='reward'?'tutorialSummon':s.settings.autoNext?'next':'map');return;}if(s.onboarding?.step==='reward'){tutorialSummon();return;}if(!s.settings.autoNext){navigate('map');return;}if(T.progress(s,r.difficulty)===21){toHome();navigate('map');return;}s.difficulty=r.difficulty;const index=T.progress(s,r.difficulty);s.run=null;depart(index);}
function finish(reason){if(s.scene!=='battle'||!s.run)return;const firstTutorial=reason==='won'&&s.run.stage===0&&!s.run.tower&&s.run.difficulty===0&&!s.clears[0],metrics=teleBattle&&teleBattle.run===s.run?{...teleBattleData(),outcome:reason==='won'?'won':reason==='retreat'?'retreat':'lost',duration_ms:Math.round(teleBattle.ms),resumed:teleBattle.resumed}:null;B.finish(s,reason);if(firstTutorial){if(s.onboarding&&s.onboarding.step!=='done')s.onboarding.step='reward';}if(reason==='won'&&s.run.first&&s.run.difficulty===0&&s.run.festival===undefined&&!s.run.tower&&s.run.stage<3){s.run.ending=window.LanternStoryV17.stage(s,s.run.stage,'after');}P.sync(s);transition(reason==='won'?'QUEST CLEAR':'帰還');Stage.clear();const saved=save();if(saved&&metrics&&teleBattle.tracked)teleEvent('battle_ended',metrics);if(saved&&reason==='won')teleEvent('reward_claimed',{source:s.run.tower?'tower':'stage',count:1});if(saved&&firstTutorial)teleEvent('tutorial_completed',{step:1});teleBattle=null;render();$('battle-caption').textContent='';if(reason==='won')victoryPresentation();else A.sfx('defeat');busy=now+.7;const r=s.run;if(reason==='won'&&r.festival===undefined&&!r.tower&&s.settings.autoNext&&!r.ending&&!r.events.length&&T.progress(s,r.difficulty)<21)autoNextAt=now+3;}
function tutorialMap(){s.scene='map';s.run=null;s.selectedChapter=0;s.onboarding={version:1,step:'map'};save();render();showModal('最初の灯をともしに',`<div class="tutorial-emblem">✦</div><p class="note">森の入口で、薪拾いの人たちが待っている<br>まずは「里外れの霧明かり」へ向かおう</p><p class="small">戦闘はAUTOで進みます</p>${btn('tutorialBattle','最初の冒険へ','primary')}`,'tutorial',false);$('modal').classList.add('tutorial-veil');}
function tutorialBattle(){showModal('アレンに道を任せよう',`<div class="tutorial-emblem">⚔</div><p class="note">アレンが自動で攻撃する<br>「連携・猛攻・堅守」をタップすると、その場で作戦が変わる</p><p class="small">敵をタップすると狙う相手を選べます<br>今は連携のままで大丈夫</p>${btn('tutorialFight','戦いを始める','primary')}`,'tutorial',false);$('modal').classList.add('tutorial-veil');}
function tutorialSummon(){s.run=null;s.scene='summon';summonTab='sigils';s.onboarding={version:1,step:'summon'};X.starter(s);save();render();showModal('星の灯が、応えている',`<div class="tutorial-emblem">✧</div><p class="note">拾った灯芯が、星灯の台座を照らした<br>紋章を宿せば、剣に属性の力が加わる</p><p class="note">はじめての贈り物：召喚券10枚<br>この券で、最初の10連召喚へ</p>${btn('tutorialDraw','贈り物の券で10連召喚','primary')}`,'tutorial',false);$('modal').classList.add('tutorial-veil');}
function tutorialDraw(){if(s.onboarding?.step!=='summon')return;const n=Math.min(10,X.ensure(s).tickets);if(n<10){s.onboarding.step='done';save();closeTutorial();return;}const drops=X.summon(s,10);if(!drops)return;s.onboarding.step='drawn';save();render();showTutorialDrops(drops);}
function showTutorialDrops(drops){showModal('君の灯に、新しい力を',`<div class="summon-results">${drops.map((a,i)=>`<div class="summon-drop rarity${a.rarity}" style="--delay:${i*.06}s;--rune-color:${X.elements[a.element].color}"><small>${X.rarities[a.rarity]} ／ ${a.duplicate?'星片 +'+a.shards:'NEW'}</small><b>${X.elements[a.element].name}</b><h3>${a.name}</h3></div>`).join('')}</div><p class="note">最初の「燠火の牙」はアレンに装着済み<br>ほかの紋章への付け替えも、育成画面でできる</p>${btn('tutorialDone','紋章を見てみよう','primary')}`,'tutorial',false);A.sfx('summon-legend');}
function closeTutorial(){modalType=null;$('modal').hidden=true;render();}
function resumeTutorial(){const step=s.onboarding?.step;if(step==='map')tutorialMap();else if(step==='battle')tutorialBattle();else if(step==='summon')tutorialSummon();else if(step==='drawn'){s.onboarding.step='done';save();navigate('party');developmentTab='sigils';render();}}
function victoryPresentation(){const run=s.run,box=$('game').getBoundingClientRect(),banner=document.createElement('div');banner.className='victory-banner';banner.innerHTML='QUEST CLEAR<small>帰り道に、またひとつ灯がともる</small>';$('game').append(banner);setTimeout(()=>banner.remove(),1850);A.sfx(run.tower&&run.tower%5===0||!run.tower&&B.stages[run.stage].chapterBoss?'victory-boss':'victory');A.sfx('reward-bloom');if(!matchMedia('(prefers-reduced-motion: reduce)').matches){const nodes=[...$('panel').querySelectorAll('[data-count]')],start=performance.now();const tick=t=>{if(s.run!==run||s.scene!=='result')return;const k=Math.min(1,(t-start)/650);for(const n of nodes)n.textContent=fmt(Math.round(Number(n.dataset.count)*(1-Math.pow(1-k,3))));if(k<1)requestAnimationFrame(tick);};requestAnimationFrame(tick);}if((run.loot||[]).some(x=>x.rarity>=2))setTimeout(()=>{if(s.run===run)A.sfx('loot-rare');},800);const pts=Stage.getPoints();run.party.forEach((p,i)=>{const q=pts?.[['hero','mina','rio','noah'][i]];if(!q)return;const el=document.createElement('span');el.className='float exp';el.textContent='EXP +'+(run.xp||(run.tower?12:0));el.style.left=q.x+'px';el.style.top=Math.max(75,Math.min(q.y-70*pts.scale,$('panel').getBoundingClientRect().top-box.top-35))+'px';$('game').append(el);setTimeout(()=>el.remove(),2000);});const level=(run.levels||[]).length;if(level)setTimeout(()=>{if(s.run===run){A.sfx('level-up');celebrate();}},580);setTimeout(()=>{if(s.run===run)A.voice?.(s.party.includes(1)?'mina':'allen','victory');},900);for(let i=0;i<4;i++)setTimeout(()=>{if(s.run===run)sparkle(box.left+box.width*(.2+i*.2),box.top+box.height*.3);},i*100);}

function floatNumbers(event){const l=Stage.getPoints(),run=s.run;if(!l)return;const special=['skill','burst'].includes(event.kind);for(const v of event.numbers||[]){const p=v.enemy!==undefined?l.enemies[v.enemy]:l[['hero','mina','rio','noah'][v.unit]];if(!p)continue;const n=Math.min(v.n,special&&event.actor===0&&!v.heal?3:1),beats=Math.max(1,n),part=Math.floor(v.n/beats);for(let i=0;i<beats;i++)setTimeout(()=>{if(s.run!==run||s.scene!=='battle')return;const el=document.createElement('span');el.className='float'+(v.heal?' heal':'')+(special?' skill-number':'')+(v.critical?' critical':'')+(v.followup?' followup':'');el.textContent=(v.heal?'+':'−')+(i===beats-1?v.n-part*(beats-1):part);el.style.left=(p.x+(i-(beats-1)/2)*12)+'px';el.style.top=(p.y-65*l.scale)+'px';$('game').append(el);setTimeout(()=>el.remove(),950);},((v.followup?.55:special?.4:event.enemyAttack?.46:.23)+i*.3)*1000/s.settings.speed);}}
function advance(){if(titleOpen||s.scene!=='battle'||modalType||now<encounterUntil||!s.settings.auto||!Stage.available(s))return;const event=B.step(s);if(!event)return;if(event.done==='wave'){B.nextWave(s);s.run.enemy=s.run.enemies[0];Stage.clear();due=now+1/s.settings.speed;save();render();$('battle-caption').textContent=s.run.wave===2?'ボス出現 ／ 灯を守れ':'WAVE 2 ／ もうひと押し';encounter();if(s.run.wave===2){A.sfx('boss-entry');const st=B.stages[s.run.stage],key='boss'+st.chapter;if(s.run.difficulty===0&&s.run.festival===undefined&&!s.run.tower&&st.chapterBoss&&!s.clears[s.run.stage]&&!s.journey.heard.includes(key)){s.journey.heard.push(key);story(window.LanternStoryV17.boss(s,st.chapter).length?window.LanternStoryV17.boss(s,st.chapter):window.LanternNarrative.chapters[st.chapter].beforeBoss,'resume');}}return;}if(event.done){finish(event.done);return;}
 lastCombatEvent=R.copy(event);Stage.action({...event,start:now*s.settings.speed});presentSkill(event);guardianPresentation(event);$('battle-caption').textContent=event.counter?event.counter+' ✦':event.title||(!event.enemyAttack?R.chars[event.actor].name+'の攻撃':'敵の攻撃');combatSound(event);battleVoice(event);floatNumbers(event);due=now+(['skill','burst'].includes(event.kind)?1.9:.92)/s.settings.speed;busy=due;save();render();}
$('game').addEventListener('pointerdown',e=>{A.enable();if(!matchMedia('(prefers-reduced-motion: reduce)').matches)sparkle(e.clientX,e.clientY);});
