$('game').addEventListener('change',e=>{if(e.target.id.startsWith('craft-')&&$('craft-cost'))$('craft-cost').textContent=cost(J.craftCost(Number($('craft-tier').value),Number($('craft-rarity').value)));if(e.target.id==='inventory-filter'){inventoryFilter=e.target.value;render();}if(e.target.id==='auto-next'){s.settings.autoNext=e.target.checked;autoNextAt=0;save();if(s.settings.autoNext&&s.run?.reason==='won'&&!s.run.ending&&!s.run.events.length&&T.progress(s,s.run.difficulty)<21)autoNextAt=now+3;}});
$('game').addEventListener('input',e=>{const k=e.target.dataset.volume;if(k){s.settings[k]=Number(e.target.value)/100;A.setVolume(s.settings[k],k);$('value-'+k).textContent=e.target.value;save();}});
document.addEventListener('keydown',e=>{A.enable();if(!modalType)return;if(e.key==='Escape'&&modalType!=='story'){closeModal();return;}if(e.key==='Tab'){const xs=[...$('modal').querySelectorAll('button:not(:disabled),input,select,summary,a[href]')];if(!xs.length)return;const first=xs[0],last=xs.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
document.addEventListener('visibilitychange',()=>{if(document.hidden){stopVoice();save();}else{lastTime=0;due=now+.7;}});window.addEventListener('pagehide',()=>{save();MT?.endSession('pagehide');});window.addEventListener('pageshow',()=>{teleLastScreen=null;teleSync();});
function resize(){const box=$('game').getBoundingClientRect(),dpr=Math.min(1,320/box.width);canvas.width=Math.round(box.width*dpr);canvas.height=Math.round(box.height*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);ctx.imageSmoothingEnabled=false;const fx=$('screen-fx');fx.width=canvas.width;fx.height=canvas.height;fx.getContext('2d').setTransform(dpr,0,0,dpr,0,0);}window.addEventListener('resize',resize);
function drawScreenFX(w,h){const c=$('screen-fx').getContext('2d');c.clearRect(0,0,w,h);if((titleOpen||s.scene==='town')&&!matchMedia('(prefers-reduced-motion: reduce)').matches){for(let i=0;i<24;i++){const phase=(now*.05+i*.123)%1;c.globalAlpha=Math.sin(phase*Math.PI)*.7;c.fillStyle=i%3?'#ffe5a5':'#ffffff';c.fillRect((i*71+Math.sin(now+i)*9)%w,h-phase*h,2+i%2,3+i%2);}}tapLights=tapLights.filter(p=>now-p.at<.8);for(const p of tapLights){const t=now-p.at;c.globalAlpha=(1-t/.8)*.8;c.fillStyle='#ffe4a3';c.fillRect(p.x+Math.cos(p.angle)*p.speed*t,p.y+Math.sin(p.angle)*p.speed*t+24*t*t,3,3);}c.globalAlpha=1;}
function frame(timestamp){if(!lastTime)lastTime=timestamp;const delta=Math.max(0,Math.min(.1,(timestamp-lastTime)/1000));now+=delta;lastTime=timestamp;teleFrame(delta);if(ready){const g=$('game').getBoundingClientRect(),p=$('panel').getBoundingClientRect(),eh=$('enemy-hud').getBoundingClientRect(),wide=g.width>g.height*1.25;Stage.draw(ctx,{width:g.width,height:g.height,time:now*s.settings.speed,state:s,floor:wide?g.height-60:s.story?Math.max(g.height*.42,($('modal').querySelector('.window')?.getBoundingClientRect().top??p.top)-g.top-12):p.top-g.top-8,ceiling:s.scene==='battle'?Math.max(96,eh.bottom-g.top+16):s.scene==='result'?32:120});drawScreenFX(g.width,g.height);if(now>toastEnd)$('notice').classList.remove('visible');A.ambientTick();if(!titleOpen&&!document.hidden&&!modalType){maybeDaily();if(!modalType&&s.scene==='battle'&&now>=due&&now>=busy)advance();else if(s.scene==='result'&&autoNextAt&&now>=autoNextAt){autoNextAt=0;continueResult();}}}requestAnimationFrame(frame);}

