  $('modal').classList.add('transfer-veil');const accept=$('modal').querySelector('[data-act="transferAccept"]'),keep=$('modal').querySelector('[data-act="transferCancel"]');accept.onclick=apply;keep.onclick=()=>{modalType=null;$('modal').hidden=true;cancel();};
